  async function friendlyRegradeSettings(gs,publishedAt){
    const defaultEnd=localDateTime(new Date(publishedAt.getTime()+7*86400000));
    let entered;
    const planned=state.activeRegradePlans?.get(gs.id);
    if(planned){if(!planned.enabled)return;entered=planned.useDefault?defaultEnd:planned.end;}
    else entered=await new Promise(resolve=>{
      publishPlan.innerHTML=`<div class="gcsi-plan-head"><div><h3>Open regrade requests?</h3><span class="gcsi-detail">Choose when regrade requests should close for <strong>${escapeHtml(gs.name)}</strong>.</span></div></div><div class="gcsi-plan-list"><div class="gcsi-plan-row"><strong>Closing date and time</strong><span class="gcsi-detail">Default: one week from now</span><input id="gcsi-single-regrade-deadline" type="datetime-local" value="${defaultEnd}" aria-label="Regrade request closing date and time"></div></div><div class="gcsi-plan-actions"><button class="gcsi-btn" id="gcsi-single-regrade-skip" type="button">Publish without regrades</button><button class="gcsi-btn gcsi-primary" id="gcsi-single-regrade-open" type="button">Open regrades</button></div>`;
      publishPlan.hidden=false;
      const finish=value=>{publishPlan.hidden=true;publishPlan.replaceChildren();resolve(value);};
      publishPlan.querySelector('#gcsi-single-regrade-skip').addEventListener('click',()=>finish(null));
      publishPlan.querySelector('#gcsi-single-regrade-open').addEventListener('click',()=>{const value=publishPlan.querySelector('#gcsi-single-regrade-deadline').value,end=new Date(value);if(!value||Number.isNaN(end.getTime())||end<=publishedAt){setMessage('Choose a closing time after publication.','bad');return;}finish(value);});
      publishPlan.querySelector('#gcsi-single-regrade-deadline').focus();
    });
    if(!entered)return;
    const end=new Date(entered);setMessage(`Opening regrade requests for ${gs.name}…`);
    try{await updateRegradesPrivate(gs,true,publishedAt,end);const resultMessage=`Opened until ${end.toLocaleString()}`;state.actionResults.set(gs.id,{ok:true,message:resultMessage});logAction(gs,'regrades',true,resultMessage);setMessage(`${gs.name}: ${resultMessage}.`,'ok');}catch(error){logAction(gs,'regrades',false,error.message);setMessage(`${gs.name}: published, but regrade requests failed — ${error.message}`,'bad');}
  }
