  function escapeHtml(value) { return String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
  function saveUiState(){sessionStorage.setItem(UI_STATE_KEY,JSON.stringify({filter:state.assignmentFilter,query:state.assignmentQuery,selected:[...state.selected]}));}
  function normalize(value) { return String(value || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim(); }
  function setMessage(text, kind='') { message.textContent=text; message.className=kind; }
  function mappings() { const value=GM_getValue(MAP_KEY, {}); return value && typeof value==='object' ? value : {}; }
  function saveMapping(gsId, canvasId) { const map=mappings(); if(canvasId) map[String(gsId)]=String(canvasId); else delete map[String(gsId)]; GM_setValue(MAP_KEY,map); state.results.delete(String(gsId)); render(); }
  function parseJsonAttr(node, name='data-react-props') { try { return JSON.parse(node?.getAttribute(name)||'{}'); } catch { return {}; } }
  function walk(value, visit, seen=new Set()) { if(!value||typeof value!=='object'||seen.has(value))return; seen.add(value); visit(value); Object.values(value).forEach(v=>walk(v,visit,seen)); }
  function assignmentUrl(value) {const item=typeof value==='object'?value:state.gsAssignments.find(entry=>String(entry.id)===String(value));return item?.url||`/courses/${courseId}/assignments/${value}`;}
  function updateGradescopeIdentity(){const course=state.gsCourse;if(!course)return;$('#gcsi-gs-course').textContent=[course.code,course.name].filter(Boolean).join(' — ')||`Course #${courseId}`;const term=$('#gcsi-gs-term');term.textContent=course.term||'';term.hidden=!course.term;}
  function semesterIn(value){return String(value||'').match(/\b(?:Spring|Summer|Fall|Winter)\s+20\d{2}\b/i)?.[0]||'';}
  function identityFromDashboard(doc){
    const card=[...doc.querySelectorAll('a[href*="/courses/"]')].find(link=>{try{return new URL(link.href,location.origin).pathname===`/courses/${courseId}`;}catch{return false;}});if(!card)return null;
    let term='';
    walk(parseJsonAttr(card),obj=>{if(!term)term=semesterIn(`${obj.semester||''} ${obj.year||''} ${obj.term||''}`);});
    for(let node=card;node&&!term;node=node.parentElement){term=semesterIn(node.getAttribute?.('data-term')||node.getAttribute?.('aria-label'));if(term)break;let sibling=node.previousElementSibling;while(sibling&&!term){term=semesterIn(sibling.matches?.('h1,h2,h3,h4,[class*="term" i]')?sibling.textContent:'');sibling=sibling.previousElementSibling;}}
    if(!term){const headings=[...doc.querySelectorAll('h1,h2,h3,h4,[class*="term" i]')].filter(node=>(node.compareDocumentPosition(card)&Node.DOCUMENT_POSITION_FOLLOWING)&&semesterIn(node.textContent));term=semesterIn(headings.at(-1)?.textContent);}
    const code=card.querySelector('.courseBox--shortname,[class*="shortname" i],[class*="courseCode" i]')?.textContent.trim()||'',name=card.querySelector('.courseBox--name,[class*="courseName" i]')?.textContent.trim()||'';
    return {code,name,term};
  }
  async function loadGradescopeIdentity(){
    for(const path of ['/','/account']){try{const response=await fetch(path,{credentials:'include'});if(!response.ok)continue;const identity=identityFromDashboard(new DOMParser().parseFromString(await response.text(),'text/html'));if(identity){state.gsCourse=identity;updateGradescopeIdentity();if(identity.term)return;}}catch{/* Try the other Gradescope dashboard route. */}}
  }

  function discoverFromDocument(doc) {
    const found = new Map(),ignoredIds=new Set(),tableData=parseJsonAttr(doc.querySelector('[data-react-class="AssignmentsTable"]')).table_data||[];
    const actionLabel = value => /^(delete|edit|duplicate|settings|publish|unpublish|regrade|download|extensions?)\b/i.test(String(value||'').trim());
    const add = (id, name, raw={}) => { if(!/^(?:\d+|container_\d+)$/.test(String(id||''))||!name||actionLabel(name))return; const key=String(id),old=found.get(key)||{}; found.set(key,{...old,...raw,id:key,name:String(name),url:raw.url||(key.startsWith('container_')?`/courses/${courseId}/assignment_containers/${key.split('_')[1]}`:`/courses/${courseId}/assignments/${key}`)}); };
    const versionsByContainer=new Map();for(const item of tableData){if(item.type==='assignment_container'){const numeric=String(item.url||'').match(/\/assignment_containers\/(\d+)/)?.[1]||String(item.id||'').match(/(\d+)$/)?.[1];if(numeric)add(`container_${numeric}`,item.title,{...item,kind:'container',containerId:numeric,versions:[]});}else if(item.is_versioned_assignment){const numeric=String(item.url||'').match(/\/assignments\/(\d+)/)?.[1];if(numeric)ignoredIds.add(numeric);const key=`container_${item.container_id}`;if(!versionsByContainer.has(key))versionsByContainer.set(key,[]);versionsByContainer.get(key).push({...item,id:numeric});}else if(item.type==='assignment'){const numeric=String(item.url||'').match(/\/assignments\/(\d+)/)?.[1];if(numeric)add(numeric,item.title,item);}}versionsByContainer.forEach((versions,key)=>{const parent=found.get(key);if(parent)parent.versions=versions.sort((a,b)=>(a.version_index||0)-(b.version_index||0));});
    doc.querySelectorAll('[data-react-props]').forEach(node => walk(parseJsonAttr(node), obj => {
      const url=String(obj.url||obj.path||''); const id=url.match(/\/assignments\/(\d+)/)?.[1] || obj.assignment_id || obj.id;
      const name=obj.title||obj.name||obj.assignment_name;
      if(!obj.is_versioned_assignment&&!ignoredIds.has(String(id))&&(url.includes('/assignments/') || obj.assignment_id)) add(id,name,obj);
    }));
    doc.querySelectorAll('a[href*="/assignments/"]').forEach(link => { const path=new URL(link.href,location.origin).pathname,match=path.match(new RegExp(`^/courses/${courseId}/assignments/(\\d+)/?$`)),name=link.textContent.replace(/\s+/g,' ').trim();if(match&&name&&!ignoredIds.has(match[1]))add(match[1],name,{url:path}); });
    if(assignmentId && !found.has(assignmentId)) add(assignmentId, doc.querySelector('h1')?.textContent.trim()||`Assignment ${assignmentId}`);
    return [...found.values()].filter(a=>a.id).sort((a,b)=>a.name.localeCompare(b.name));
  }

  async function discoverAssignments() {
    await loadGradescopeIdentity();
    let list=discoverFromDocument(document);
    if(!location.pathname.match(/^\/courses\/\d+\/?$/) && !location.pathname.endsWith('/assignments')) {
      const response=await fetch(`/courses/${courseId}/assignments`,{credentials:'include'}); if(response.ok){const doc=new DOMParser().parseFromString(await response.text(),'text/html'); const more=discoverFromDocument(doc); const map=new Map([...list,...more].map(a=>[a.id,a])); list=[...map.values()].sort((a,b)=>a.name.localeCompare(b.name));}
    }
    state.gsAssignments=list; render();loadRegradeStatuses();
    await loadCanvasCourses();
  }

  function canvasRequest(url) { return new Promise((resolve,reject)=>GM_xmlhttpRequest({method:'GET',url:url.startsWith('http')?url:`${CANVAS}${url}`,withCredentials:true,headers:{Accept:'application/json'},timeout:30000,onload:r=>{const type=r.responseHeaders.match(/content-type:\s*([^\r\n]+)/i)?.[1]||'';if(r.status<200||r.status>=300||!type.includes('json'))return reject(new Error('Canvas did not return API data. Sign into Canvas in another tab and try again.'));try{resolve({data:JSON.parse(r.responseText),headers:r.responseHeaders});}catch{reject(new Error('Canvas returned unreadable data.'));}},onerror:()=>reject(new Error('Could not reach Canvas. Check Tampermonkey permissions.')),ontimeout:()=>reject(new Error('Canvas timed out.'))})); }
