    state.canvasCourseId=id; GM_setValue(COURSE_KEY,id); setBusy(true); setMessage('Loading Canvas assignments…');
    try { state.canvasAssignments=await canvasPages(`/api/v1/courses/${id}/assignments?per_page=100`);const course=state.canvasCourses.find(item=>String(item.id)===id),term=course?.term?.name||$('#gcsi-term option:checked')?.textContent?.replace(/^★\s*/, '')||'';$('#gcsi-connected-course').textContent=`${course?.course_code||course?.name||`Course ${id}`}${term?` · ${term}`:''}`;setup.classList.add('gcsi-collapsed');courseSummary.hidden=false;render(); setMessage(`Loaded ${state.canvasAssignments.length} Canvas assignments. Choose mappings, then check grades.`,'ok'); }
