  function publishedStatus(gs) {if(state.published.has(gs.id))return state.published.get(gs.id)?['Published','ok']:['Not published','warn'];const raw=[gs.is_published,gs.grades_published,gs.published,gs.publish_status,gs.status].find(v=>v!==undefined); if(raw===false||/unpublished/i.test(String(raw)))return ['Not published','warn']; if(raw===true||/published/i.test(String(raw)))return ['Published','ok']; return ['Check assignment','warn']; }
