  function resultCell(result) { if(!result)return ['Not checked','']; if(result.error)return ['Could not compare','bad',result.error]; const issues=[result.differences?`${result.differences} score difference${result.differences===1?'':'s'}`:'',result.unmatched?`${result.unmatched} unmatched`:'' ].filter(Boolean).join(' · ');if(issues)return [`Review: ${issues}`,'bad',`${result.compared} students compared. Select this result to review the affected students.`];if(result.compared===0)return ['No students matched','bad','No student identities could be matched between the Gradescope export and Canvas.'];return [`Agree (${result.compared})`,'ok','Every matched numeric score agrees.']; }
