  async function regradeSettingsDocument(gs){const response=await fetch(`${assignmentUrl(gs)}/regrade_requests`,{credentials:'include',cache:'no-store'});if(!response.ok)throw new Error(`Regrade Requests page failed (${response.status}).`);return new DOMParser().parseFromString(await response.text(),'text/html');}
  function regradeFormLabel(form){return `${form.textContent||''} ${[...form.querySelectorAll('button,input[type="submit"]')].map(controlText).join(' ')}`;}
  function regradeInfoFromDocument(doc){const end=doc.querySelector('input[name$="[regrade_request_end_string]"]'),forms=[...doc.querySelectorAll('form')],disable=forms.find(form=>form.querySelector('input[name$="[regrades_enabled]"]')&&/disable regrade requests/i.test(regradeFormLabel(form)));if(disable)return {enabled:true,end:end?.value||''};const toggle=forms.find(form=>form.querySelector('input[name$="[regrades_enabled]"]')&&/enable regrade requests/i.test(regradeFormLabel(form)));if(toggle)return {enabled:false,end:''};const checkbox=doc.querySelector('#assignment_regrades_enabled');if(checkbox&&end)return {enabled:checkbox.checked,end:end.value||''};const heading=doc.querySelector('.statusIndicatorHeading')?.textContent||'';if(/regrade requests open/i.test(heading))return {enabled:true,end:end?.value||''};if(/regrade requests (?:closed|disabled)/i.test(heading))return {enabled:false,end:''};return null;}
