    const token=document.querySelector('meta[name="csrf-token"]')?.content||settingsDoc?.querySelector('meta[name="csrf-token"]')?.content||settingsDoc?.querySelector('input[name="authenticity_token"]')?.value||'';
    if(!token)throw new Error('Gradescope security token was unavailable. Refresh Gradescope and retry.');
