  function renderRegradeControls(){rows.querySelectorAll('.gcsi-regrade-status,.gcsi-regrades-one').forEach(node=>node.remove());rows.querySelectorAll('tr[data-gs]').forEach(tr=>{const gs=state.gsAssignments.find(item=>item.id===tr.dataset.gs);if(!gs)return;const info=state.regrades.get(gs.id),status=document.createElement('small');status.className=`gcsi-detail gcsi-status gcsi-regrade-status ${info?.enabled?'ok':info?.enabled===false?'warn':''}`;status.textContent=info?.enabled?`Regrades open${info.end?` until ${new Date(info.end).toLocaleString()}`:''}`:info?.enabled===false?'Regrades closed':info?.unavailable?'Regrades unavailable':'Checking regrades…';tr.children[2]?.append(status);const button=document.createElement('button');button.type='button';button.className='gcsi-btn gcsi-regrades-one';button.textContent=info?.enabled?'Disable regrades':'Enable regrades';button.disabled=state.busy||info?.enabled==null||(!info.enabled&&!isAssignmentPublished(gs));button.title=!info?.enabled&&!isAssignmentPublished(gs)?'Publish this assignment before enabling regrades':'';button.addEventListener('click',()=>toggleRegrades(gs));tr.querySelector('.gcsi-actions')?.append(button);});}
