  function enhanceDashboard(){const chips=[...$('#gcsi-summary').querySelectorAll('.gcsi-chip')],filters=['all','ready','readypost','canvashidden','workflowchanged','attention','workflowcomplete'];chips.forEach((chip,index)=>{chip.title='Filter assignments';chip.onclick=()=>{const filter=filters[index]||'all';state.assignmentFilter=filter;$('#gcsi-assignment-filter').value=filter;filterChips.querySelectorAll('.gcsi-filter-chip').forEach(item=>item.classList.toggle('active',item.dataset.filter===filter));render();};});}
