    rows.querySelectorAll('tr[data-gs]').forEach(tr=>{const gs=state.gsAssignments.find(a=>a.id===tr.dataset.gs),timing=deadlineState(gs),cell=document.createElement('td');cell.innerHTML=`<span class="gcsi-status ${timing.className}">${escapeHtml(timing.label)}</span><small class="gcsi-detail">${escapeHtml(timing.detail)}</small>`;tr.lastElementChild.before(cell);});rows.querySelector('tr:not([data-gs]) td')?.setAttribute('colspan','6');
