  function setBusy(value){state.busy=value;panel.querySelectorAll('button').forEach(b=>{if(b.id!=='gcsi-close')b.disabled=value||(b.classList.contains('gcsi-one')&&!matchedCanvas(state.gsAssignments.find(a=>a.id===b.closest('tr')?.dataset.gs)));});if(!value)render();}
  function parseCsv(text) { const out=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(c==='"'&&quoted&&n==='"'){cell+='"';i++;}else if(c==='"')quoted=!quoted;else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&n==='\n')i++;row.push(cell);if(row.some(v=>v!==''))out.push(row);row=[];cell='';}else cell+=c;}if(cell||row.length){row.push(cell);out.push(row);}return out; }
  function column(headers, patterns){return headers.findIndex(h=>patterns.some(p=>p.test(normalize(h))));}
  function identityKeys(...values){const keys=new Set();values.forEach(value=>{const clean=String(value||'').trim().toLowerCase();if(!clean)return;keys.add(clean);if(clean.includes('@'))keys.add(clean.split('@')[0]);});return [...keys];}
  function isTestStudent(...values){return values.some(value=>normalize(value)==='test student');}
  function encodeCsv(rows){return rows.map(row=>row.map(value=>{const text=String(value??'');return /[",\r\n]/.test(text)?`"${text.replace(/"/g,'""')}"`:text;}).join(',')).join('\r\n');}
